// The icon of a Random Mix type (the command word of the type).
fun randomMixIcon(type: String): ImageVector = when (type) {
    "albums" -> RandomAlbumsIcon
    "contributors" -> RandomContributorsIcon
    "work" -> RandomWorksIcon
    "year" -> RandomYearIcon
    else -> RandomTracksIcon
}
